import{_ as t,a0 as l,w as o,s as r,ao as c,I as p,x as a,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"如何在 Kubernetes 集群上安装 Ansible AWX | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Kubernetes 集群上安装 Ansible AWX | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Kubernetes 集群上安装 Ansible AWX | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Kubernetes 集群上安装 Ansible AWX | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20230524.1 ⭐️⭐️ How to Install Ansible AWX on Kubernetes Cluster","title":"如何在 Kubernetes 集群上安装 Ansible AWX","tag":"202306","desc":""},"relativePath":"202306/20230524.1 ⭐️⭐️ How to Install Ansible AWX on Kubernetes Cluster.md","filePath":"[post].md"}'),d={name:"202306/20230524.1 ⭐️⭐️ How to Install Ansible AWX on Kubernetes Cluster.md"};function h(b,s,g,u,k,m){const e=l("Link");return o(),r("div",null,[s[15]||(s[15]=c(`<h1 id="如何在-kubernetes-集群上安装-ansible-awx" tabindex="-1">如何在 Kubernetes 集群上安装 Ansible AWX <a class="header-anchor" href="#如何在-kubernetes-集群上安装-ansible-awx" aria-label="Permalink to “如何在 Kubernetes 集群上安装 Ansible AWX”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202306/25/172630f134fo6cg5gcodu4.jpg" alt=""></p><blockquote><p>在本文中，我们将逐步向你展示如何在 Kubernetes（k8s）集群上安装 Ansible AWX。</p></blockquote><p>Ansible AWX 是一个强大的开源工具，用于管理和自动化 IT 基础设施。AWX 为 Ansible 提供图形用户界面，使你可以轻松创建、安排和运行 Ansible <ruby>剧本<rt>Playbook</rt></ruby>。</p><p>另一方面，Kubernetes 是一种流行的容器编排平台，广泛用于部署和管理容器化应用。</p><p>先决条件：</p><ul><li>Kubernetes 集群</li><li>Kubectl</li><li>具有 sudo 权限和集群管理员权限的普通用户</li><li>互联网连接</li></ul><h3 id="步骤-1-安装-helm" tabindex="-1">步骤 1：安装 Helm <a class="header-anchor" href="#步骤-1-安装-helm" aria-label="Permalink to “步骤 1：安装 Helm”">​</a></h3><p>如果你的系统上安装了 Helm，则在命令下运行以进行安装，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -fsSL -o get_helm.sh https://raw.githubusercontent.com/helm/helm/main/scripts/get-helm-3</span></span>
<span class="line"><span>$ chmod +x get_helm.sh</span></span>
<span class="line"><span>$ ./get_helm.sh</span></span>
<span class="line"><span>$ helm version</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/Install-helm-linux-command-line.png?ezimgfmt=rs%3Adevice%2Frscb22-1" alt="Install-helm-linux-command-line"></p><h3 id="步骤-2-安装-awx-chart" tabindex="-1">步骤 2：安装 AWX chart <a class="header-anchor" href="#步骤-2-安装-awx-chart" aria-label="Permalink to “步骤 2：安装 AWX chart”">​</a></h3><p>在 Kubernetes 上安装 AWX 的最简单方法是使用 AWX Helm “<ruby>海图<rt>chart</rt></ruby>”。因此，要通过 “海图” 安装 AWX，首先使用以下 <code>helm</code> 命令添加仓库。（LCTT 译注：Kubernetes 生态中大量使用了和航海有关的比喻，因此本文在翻译时也采用了这些比喻）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ helm repo add awx-operator https://ansible.github.io/awx-operator/</span></span>
<span class="line"><span>&quot;awx-operator&quot; has been added to your repositories</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>注意：如果你之前已经添加过此仓库，请在命令下运行以获取最新版本的软件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ helm repo update</span></span></code></pre></div><p>要通过 Helm 安装 awx-operator，请运行:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ helm install ansible-awx-operator awx-operator/awx-operator -n awx --create-namespace</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/helm-install-awx-operator-kubernetes.png" alt="helm-install-awx-operator-kubernetes"></p><p>这将下载 AWX 海图并将其安装在 <code>awx</code> 命名空间中的 Kubernetes 集群上。安装过程可能需要几分钟，请耐心等待。</p><h3 id="步骤-3-验证-awx-操作员安装" tabindex="-1">步骤 3：验证 AWX 操作员安装 <a class="header-anchor" href="#步骤-3-验证-awx-操作员安装" aria-label="Permalink to “步骤 3：验证 AWX 操作员安装”">​</a></h3><p>安装成功后，你可以通过运行以下命令来验证 AWX <ruby>操作员<rt>operator</rt></ruby> 状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo kubectl get pods -n awx</span></span></code></pre></div><p>你应该看到这样的东西：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/awx-operator-pod-status-kubectl.png" alt="awx-operator-pod-status-kubectl"></p><h3 id="步骤-4-创建-pv、pvc-并部署-awx-yaml-文件" tabindex="-1">步骤 4： 创建 PV、PVC 并部署 AWX yaml 文件 <a class="header-anchor" href="#步骤-4-创建-pv、pvc-并部署-awx-yaml-文件" aria-label="Permalink to “步骤 4： 创建 PV、PVC 并部署 AWX yaml 文件”">​</a></h3><p>AWX 需要 postgres <ruby>容器荚<rt>pod</rt></ruby> 的持久卷。那么，让我们首先为本地卷创建一个存储类。</p><p>注意：在本文中，我使用本地文件系统作为持久卷。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi local-storage-class.yaml</span></span>
<span class="line"><span>apiVersion: storage.k8s.io/v1</span></span>
<span class="line"><span>kind: StorageClass</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: local-storage</span></span>
<span class="line"><span>  namespace: awxprovisioner: kubernetes.io/no-provisioner</span></span>
<span class="line"><span>volumeBindingMode: WaitForFirstConsumer</span></span></code></pre></div><p>保存并关闭文件，然后运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl create -f local-storage-class.yaml</span></span>
<span class="line"><span>$ kubectl get sc -n awx</span></span>
<span class="line"><span>NAME            PROVISIONER                    RECLAIMPOLICY   VOLUMEBINDINGMODE      ALLOWVOLUMEEXPANSION   </span></span>
<span class="line"><span>local-storage   kubernetes.io/no-provisioner   Delete          WaitForFirstConsumer   false                 </span></span>
<span class="line"><span>$</span></span></code></pre></div><p>接下来使用以下 <code>pv.yaml</code> 文件创建持久卷（PV）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi pv.yaml</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>kind: PersistentVolume</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: postgres-pv</span></span>
<span class="line"><span>  namespace: awx</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  capacity:</span></span>
<span class="line"><span>    storage: 10Gi</span></span>
<span class="line"><span>  volumeMode: Filesystem</span></span>
<span class="line"><span>  accessModes:</span></span>
<span class="line"><span>  - ReadWriteOnce</span></span>
<span class="line"><span>  persistentVolumeReclaimPolicy: Delete</span></span>
<span class="line"><span>  storageClassName: local-storage</span></span>
<span class="line"><span>  local:</span></span>
<span class="line"><span>    path: /mnt/storage</span></span>
<span class="line"><span>  nodeAffinity:</span></span>
<span class="line"><span>    required:</span></span>
<span class="line"><span>      nodeSelectorTerms:</span></span>
<span class="line"><span>      - matchExpressions:</span></span>
<span class="line"><span>        - key: kubernetes.io/hostname</span></span>
<span class="line"><span>          operator: In</span></span>
<span class="line"><span>          values:</span></span>
<span class="line"><span>          - k8s-worker</span></span></code></pre></div><p>保存并退出文件。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/Postgres-pv-awx-kubernetes.png" alt="Postgres-pv-awx-kubernetes"></p><p>重要说明：确保文件夹 <code>/mnt/storage</code> 存在于工作节点上，如果不存在，则在工作节点上使用 <code>mkdir</code> 命令创建它。在我们的例子中，工作节点是 <code>k8s-worker</code>。</p><p>执行下面的命令在 <code>awx</code> 命名空间中创建 <code>postgres-pv</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl create -f pv.yaml</span></span></code></pre></div><p>成功创建 PV 后，使用 <code>pvc.yaml</code> 文件创建 PersistentVolumeClaim：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi  pvc.yaml</span></span>
<span class="line"><span>apiVersion: v1</span></span>
<span class="line"><span>kind: PersistentVolumeClaim</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: postgres-13-ansible-awx-postgres-13-0</span></span>
<span class="line"><span>  namespace: awx</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  storageClassName: local-storage</span></span>
<span class="line"><span>  accessModes:</span></span>
<span class="line"><span>    - ReadWriteOnce</span></span>
<span class="line"><span>  resources:</span></span>
<span class="line"><span>    requests:</span></span>
<span class="line"><span>      storage: 10Gi</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/posgres-pvx-awx-kubernetes.png" alt="posgres-pvc-awx-kubernetes"></p><p>要创建 PVC，请运行以下 <code>kubectl</code> 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl create -f pvc.yaml</span></span></code></pre></div><p>使用下面的命令验证 PV 和 PVC 的状态：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl get pv,pvc -n awx</span></span></code></pre></div><p>现在，我们都准备好部署 AWX 实例了。创建一个包含以下内容的 <code>ansible-awx.yaml</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi ansible-awx.yaml</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>apiVersion: awx.ansible.com/v1beta1</span></span>
<span class="line"><span>kind: AWX</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span>  name: ansible-awx</span></span>
<span class="line"><span>  namespace: awx</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span>  service_type: nodeport</span></span>
<span class="line"><span>  postgres_storage_class: local-storage</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/Ansible-awx-yaml-file.png" alt="Ansible-awx-yaml-file"></p><p>保存并关闭文件。</p><p>执行以下 <code>kubectl</code> 命令来部署 awx 实例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl create -f ansible-awx.yaml</span></span></code></pre></div><p>等待几分钟，然后检查 <code>awx</code> 命名空间中的容器荚状态。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl get pods -n awx</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/Ansible-AWX-Pods-Status-Kubernetes.png" alt="Ansible-AWX-Pods-Status-Kubernetes"></p><h3 id="步骤-5-访问-awx-web-界面" tabindex="-1">步骤 5：访问 AWX Web 界面 <a class="header-anchor" href="#步骤-5-访问-awx-web-界面" aria-label="Permalink to “步骤 5：访问 AWX Web 界面”">​</a></h3><p>要访问 AWX Web 界面，你需要创建一个公开 awx-web 部署的服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl expose deployment ansible-awx-web --name ansible-awx-web-svc --type NodePort -n awx</span></span></code></pre></div><p>此命令将创建一个 <code>NodePort</code> 服务，该服务将 AWX Web 容器的端口映射到 Kubernetes 节点上的端口。你可以通过运行以下命令找到端口号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl get svc ansible-awx-web-svc  -n awx</span></span></code></pre></div><p>这将输出如下内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>NAME                 TYPE       CLUSTER-IP      EXTERNAL-IP   PORT(S)          AGE</span></span>
<span class="line"><span>ansible-awx-web-svc   NodePort   10.99.83.248   &lt;none&gt;        8052:32254/TCP   82s</span></span></code></pre></div><p>在此示例中，Web 服务在端口 32254 上可用。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/Expose-Ansible-AWX-Web-NodePort-Kubernetes.png" alt="Expose-Ansible-AWX-Web-NodePort-Kubernetes"></p><p>默认情况下，admin 用户是 Web 界面的 <code>admin</code>，密码在 <code>&lt;resourcename&gt;-admin-password</code> 机密信息中。要检索管理员密码，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ kubectl get secrets -n awx | grep -i admin-password</span></span>
<span class="line"><span>ansible-awx-admin-password        Opaque               1      109m</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ kubectl get secret ansible-awx-admin-password -o jsonpath=&quot;{.data.password}&quot; -n awx | base64 --decode ; echo</span></span>
<span class="line"><span>l9mWcIOXQhSKnzZQyQQ9LZf3awDV0YMJ</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>你现在可以打开 Web 浏览器并进入 <code>http://&lt;node-ip&gt;:&lt;node-port&gt;/</code> 来访问 AWX Web 界面。在上面的示例中，URL 是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://192.168.1.223:3225</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/AWX-Login-URL-Kubernetes.png" alt="AWX-Login-URL-Kubernetes"></p><p>输入凭据后单击登录。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2023/05/Ansible-AWX-Web-Dashboard.png" alt="Ansible-AWX-Web-Dashboard"></p><p>恭喜！ 你已在 Kubernetes 上成功安装 Ansible AWX。你现在可以使用 AWX 来自动化你的 IT 基础架构，并让你作为系统管理员的生活更轻松。</p><p><em>（题图：MJ/bfd354aa-2ee5-4555-98b8-ac5207cbeabe）</em></p><hr>`,73)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.linuxtechi.com/install-ansible-awx-on-kubernetes-cluster/"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/install-ansible-awx-on-kubernetes-cluster/",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:i(()=>[...s[2]||(s[2]=[a("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),n(e,{href:"https://github.com/lkxed/"},{default:i(()=>[...s[3]||(s[3]=[a("lkxed",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const y=t(d,[["render",h]]);export{f as __pageData,y as default};
